-- org_combined
SELECT owner, tupleElement(k, 1) AS day_s, tupleElement(k, 2) AS actor,
  countIf(event_type = 'PushEvent') AS push,
  countIf(event_type = 'PullRequestEvent') AS pr,
  countIf(event_type = 'IssuesEvent') AS issues,
  countIf(event_type = 'ReleaseEvent') AS release,
  count() AS n_all,
  formatDateTime(min(created_at), '%Y-%m-%d %H:%i:%S', 'UTC') AS first_ts,
  formatDateTime(max(created_at), '%Y-%m-%d %H:%i:%S', 'UTC') AS last_ts,
  formatDateTime(minIf(created_at, event_type = 'PushEvent'), '%Y-%m-%d %H:%i:%S', 'UTC') AS first_push_ts
FROM (SELECT lower(if(position(repo_name, '/') > 0, substring(repo_name, 1, position(repo_name, '/') - 1), '')) AS owner, created_at, event_type, lower(actor_login) AS al
      FROM github_events
      WHERE owner IN ('10to1', '3dgi', '404rq', '42floors', '42gems', '42technologies', '757rb', '7learnings', '99minutos', '9gag', '9mothers', 'abatable', 'ablehealth', 'academind', 'accessowl', 'activepieces', 'adapei-meuse', 'adaptyvbio', 'adlatusrobotics', 'adsota', 'advanova', 'adyptation', 'aegiq', 'aerochimps', 'aerotime', 'afrostream', 'afterquery', 'afterverse', 'ahazou', 'aignostics', 'airfordable', 'airgateway', 'airmyne', 'airpair', 'aitoair', 'akanda', 'algolia', 'alignedcode', 'alinea-invest', 'all3dp', 'allaboutapps', 'alphaflow', 'altavo', 'altruja', 'alude', 'amalinvest', 'aminoanalytica', 'amplitude', 'ancestry', 'andonapp', 'angstrom-ai', 'animaapp', 'anki', 'anna-dsb', 'anniecannons', 'anybill', 'aon3d', 'apequest', 'apollographql', 'applanga', 'appmetr', 'appsidekit', 'aptdeco', 'apteco', 'aptible', 'arcprize', 'arengu', 'argalabs', 'armorerlabs', 'armory', 'ashbyhq', 'assemblyai', 'asseth', 'assistant-ui', 'athenlabs', 'atopile', 'audm', 'australiandiabetescouncil', 'authy', 'authzed', 'autosana', 'auv-iitb', 'aventyret', 'avionschool', 'axdraft', 'axiomzen', 'backerkit', 'ballpointcg', 'banditml', 'banxware', 'basedash', 'baubap', 'bayesimpact', 'bearflagrobotics', 'beek', 'beeper', 'beezwax', 'belvedir', 'bemyeyes', 'berlinjs', 'better-auth', 'bettyblocks', 'bimaplan', 'bintics', 'bioarchlinux', 'bioschemas', 'bitaccess', 'bitechnologies', 'bitlogic', 'bitloops', 'bitmovin', 'bitnami', 'bitpatrol', 'blackrockneurotech', 'blindsidenetworks', 'blockspring', 'bluecargo', 'bluefroggaming', 'bndtools', 'bodyport', 'bolsterbuilt', 'bonsaierp', 'boostable', 'bottomless', 'box-id', 'brainkey', 'braintripping', 'brandyourself', 'breadfast', 'bridg', 'bridgetownpartners', 'briohr', 'browser-use', 'browserstack', 'bsdtw', 'budibase', 'bugtothefeature', 'buildjet', 'buildscience', 'buildspace', 'bukuwarung', 'bulldozair', 'bundlenews', 'bunkerhillhealth', 'buntinglabs', 'buttercoin', 'buypower', 'cadencework', 'cambly', 'capimoney', 'capmo', 'captivateiq